# WARNING: Under review - generated by LLM.

import pytest

from .tiny_llm_base import (
    SessionStore,
    ToolPolicy,
    Workspace,
    run_agent,
)


def responses(*items):
    queue = iter(items)
    return lambda messages: next(queue)


def test_task_1_session_events_round_trip_and_persist(tmp_path):
    store = SessionStore(tmp_path, "test-model")
    session = store.create()
    call = session.append("tool_call", tool="read_file", arguments={"path": "a"})
    session.append(
        "tool_result",
        tool_call_id=call.id,
        tool="read_file",
        is_error=False,
        content="data",
    )

    reloaded = store.load(session.session_id, recover=False)
    assert [event.type for event in reloaded.events] == [
        "session_started",
        "tool_call",
        "tool_result",
    ]


def test_task_2_loop_records_durable_events(tmp_path):
    store = SessionStore(tmp_path, "test-model")
    session = store.create()
    workspace = Workspace(ToolPolicy(tmp_path))

    result = run_agent(
        "inspect the project",
        responses('{"tool":"list_files"}', '{"final":"done"}'),
        workspace,
        session=session,
    )

    assert result.completed
    assert result.session_id == session.session_id
    types = [event.type for event in session.events]
    assert "user_message" in types
    assert "run_started" in types
    assert "tool_call" in types
    assert "tool_result" in types
    assert "run_finished" in types


def test_task_2_invalid_json_is_recorded_without_execution(tmp_path):
    store = SessionStore(tmp_path, "test-model")
    session = store.create()
    workspace = Workspace(ToolPolicy(tmp_path))

    result = run_agent(
        "inspect the project",
        responses("not json", '{"final":"recovered"}'),
        workspace,
        session=session,
    )

    assert result.completed
    tool_results = [event for event in session.events if event.type == "tool_result"]
    assert len(tool_results) == 1
    assert tool_results[0].data["is_error"] is True
    assert tool_results[0].data["tool_call_id"] is None


def test_task_3_active_path_of_root_session_is_just_the_root(tmp_path):
    store = SessionStore(tmp_path, "test-model")
    root = store.create()

    assert store.active_path(root.session_id) == (root.session_id,)
    assert store.parent_of(root.session_id) is None


def test_task_3_branch_builds_a_two_level_active_path(tmp_path):
    store = SessionStore(tmp_path, "test-model")
    root = store.create()
    root.append("user_message", content="task one")
    branch = store.branch(root.session_id, at_event_id=root.events[-1].id)

    path = store.active_path(branch.session_id)
    assert path == (root.session_id, branch.session_id)
    assert store.parent_of(branch.session_id) == (
        root.session_id,
        root.events[-1].id,
    )


def test_task_3_active_path_events_are_deterministic(tmp_path):
    store = SessionStore(tmp_path, "test-model")
    root = store.create()
    root.append("user_message", content="task one")
    branch = store.branch(root.session_id, at_event_id=root.events[-1].id)
    branch.append("user_message", content="branch follow-up")

    first = branch.active_path_events()
    second = branch.active_path_events()

    assert [event.id for event in first] == [event.id for event in second]
    assert first[-1].data.get("content") == "branch follow-up"


def test_task_3_branch_keeps_the_full_inherited_prefix(tmp_path):
    store = SessionStore(tmp_path, "test-model")
    root = store.create()
    root.append("user_message", content="task one")
    branch = store.branch(root.session_id, at_event_id=root.events[-1].id)

    events = branch.active_path_events()
    types = [event.type for event in events]
    assert "branch_created" in types
    assert "branch_completed" in types
    assert types.count("user_message") == 1


def test_task_3_grandchild_path_orders_root_first(tmp_path):
    store = SessionStore(tmp_path, "test-model")
    root = store.create()
    root.append("user_message", content="task one")
    branch = store.branch(root.session_id, at_event_id=root.events[-1].id)
    branch.append("user_message", content="branch follow-up")
    child = store.branch(branch.session_id, at_event_id=branch.events[-1].id)

    assert store.active_path(child.session_id) == (
        root.session_id,
        branch.session_id,
        child.session_id,
    )


def test_task_3_active_path_rejects_an_unknown_session(tmp_path):
    store = SessionStore(tmp_path, "test-model")

    with pytest.raises(ValueError):
        store.active_path("0" * 32)
